import numpy as np

rng = np.random.default_rng(0)


def make_params(rng):
    return {
        'W1': rng.standard_normal((4, 32)) * 0.5, 'b1': np.zeros(32),
        'g1': np.ones(32), 'be1': np.zeros(32),
        'W2': rng.standard_normal((32, 16)) * 0.5, 'b2': np.zeros(16),
        'g2': np.ones(16), 'be2': np.zeros(16),
        'W3': rng.standard_normal((16, 3)) * 0.5, 'b3': np.zeros(3),
    }


def linear(x, W, b):
    return x @ W + b


def batch_norm(x, gamma, beta, eps=1e-5):
    mu = x.mean(axis=0)
    var = x.var(axis=0)
    return gamma * (x - mu) / np.sqrt(var + eps) + beta


def relu(x):
    return np.maximum(x, 0)


def forward(X, p):
    h = relu(batch_norm(linear(X, p['W1'], p['b1']), p['g1'], p['be1']))
    h = relu(batch_norm(linear(h, p['W2'], p['b2']), p['g2'], p['be2']))
    return linear(h, p['W3'], p['b3'])


def count_params(p):
    return sum(a.size for a in p.values())


params = make_params(rng)
X = rng.standard_normal((10, 4))
output = forward(X, params)
print(f'Output shape: {output.shape}')
print(f'Total parameters: {count_params(params)}')
